SELECT p.ViewCount
FROM posts p
WHERE p.Title = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer';

SELECT u.DisplayName
FROM users u
WHERE u.WebsiteUrl = 'http://stackoverflow.com';

SELECT COUNT(*) AS TotalComments
FROM comments
WHERE comments.UserId = 13;

SELECT 100.0 * SUM(CASE WHEN YEAR(Date) = 2010 THEN 1 ELSE 0 END) / COUNT(*) - 100.0 * SUM(CASE WHEN YEAR(Date) = 2011 THEN 1 ELSE 0 END) / COUNT(*) AS percentage_difference
FROM badges
WHERE Name = 'Student';

SELECT p.Id, p.OwnerUserId
FROM posts p
WHERE p.Score > 60;

SELECT COUNT(DISTINCT b.UserId) AS user_count
FROM badges b
WHERE b.Name = 'Announcer';

SELECT DISTINCT badges.Name
FROM badges
WHERE badges.Date = '2010-07-19 19:39:08.0';

SELECT COUNT(CASE WHEN b.Name = 'Teacher' THEN 1 END) * 100.0 / COUNT(b.UserId) AS percentage
FROM badges b
JOIN users u ON u.Id = b.UserId;

SELECT COUNT(*) AS adult_users
FROM users
WHERE users.Age BETWEEN 19 AND 65;

SELECT u.DisplayName, u.Age
FROM users u
WHERE u.Views = (SELECT MAX(u2.Views) FROM users u2);

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT p.OwnerUserId
FROM posts p
WHERE p.FavoriteCount = (SELECT MAX(p2.FavoriteCount) FROM posts p2);

SELECT u.Id
FROM users u
WHERE u.Age = (SELECT MIN(u2.Age) FROM users u2);

SELECT DisplayName
FROM users
WHERE Reputation = (SELECT MAX(Reputation) FROM users);

SELECT COUNT(CASE WHEN Reputation > 1000 THEN Id END) * 100.0 / COUNT(Id) AS Percentage
FROM users
WHERE YEAR(CreationDate) = 2011;

SELECT COUNT(*) AS TotalPosts
FROM posts
WHERE ViewCount > (SELECT AVG(ViewCount) FROM posts);

SELECT COUNT(DISTINCT b.UserId) AS UserCount
FROM badges b
WHERE b.Name = 'Citizen Patrol';

SELECT Reputation, Views
FROM users
WHERE DisplayName = 'Jarrod Dixon';

SELECT u.CreationDate
FROM users u
WHERE u.DisplayName = 'IrishStat';

SELECT ExcerptPostId, WikiPostId
FROM tags
WHERE TagName = 'sample';

SELECT SUM(CASE WHEN c.Currency = 'CZK' THEN 1 ELSE 0 END) - SUM(CASE WHEN c.Currency = 'EUR' THEN 1 ELSE 0 END) AS more_smes
FROM customers c
WHERE c.Segment = 'SME';

SELECT 100.0 * SUM(CASE WHEN c.Currency = 'EUR' THEN 1 ELSE 0 END) / COUNT(*) AS pct_kam_eur
FROM customers c
WHERE c.Segment = 'KAM';

SELECT SUM(CASE WHEN y.Consumption > 528.3 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM yearmonth AS y
WHERE y.Date = '201202';

SELECT SUM(CASE WHEN g.Segment = 'Premium' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM gasstations g
WHERE g.Country = 'SVK';

SELECT AVG(Price) AS average_total_price
FROM transactions_1k
WHERE Date LIKE '2012-01%';

SELECT CAST(100.0 * SUM(CASE WHEN g.Segment = 'Premium' THEN 1 ELSE 0 END) / COUNT(*) AS DECIMAL(10,2)) AS premium_percentage
FROM gasstations g
WHERE g.Country = 'SVK';

SELECT player_api_id
FROM Player_Attributes
WHERE overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes);

SELECT SUM(P.height) / COUNT(P.id) AS average_height
FROM Player AS P
WHERE P.birthday >= '1990-01-01 00:00:00' AND P.birthday < '1996-01-01 00:00:00';

SELECT DISTINCT team_fifa_api_id
FROM Team_Attributes
WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;

SELECT player_name
FROM Player
WHERE substr(birthday, 1, 7) = '1970-10';

SELECT p.player_name
FROM Player p
WHERE p.height > 180;

SELECT player_name
FROM Player
WHERE height = (SELECT MIN(height) FROM Player);

SELECT T.team_long_name
FROM Team T
WHERE T.team_short_name = 'GEN';

SELECT p.player_name, p.height
FROM Player p
WHERE p.height = (SELECT MAX(p2.height) FROM Player p2);

SELECT P.player_name
FROM Player P
WHERE P.height = (SELECT MAX(P2.height) FROM Player P2);

SELECT player_name
FROM Player
WHERE datetime(CURRENT_TIMESTAMP, 'localtime') - datetime(birthday) > 34;

SELECT CAST(COUNT(DISTINCT CASE WHEN PA.strength > 80 AND PA.stamina > 80 THEN PA.player_api_id END) AS REAL) * 100.0 / COUNT(DISTINCT PA.player_api_id) AS percentage
FROM Player_Attributes PA
JOIN Player P ON PA.player_api_id = P.player_api_id;

SELECT COUNT(CASE WHEN p.height < 180 AND pa.overall_rating > 70 THEN 1 END) * 100.0 / COUNT(pa.id) AS percentage
FROM Player p
INNER JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id;

SELECT SUM(CASE WHEN status = 'C' THEN amount ELSE 0 END) * 100.0 / SUM(amount) AS percentage
FROM loan
WHERE amount < 100000;

SELECT expense_description
FROM expense
WHERE cost = (SELECT MAX(cost) FROM expense);

SELECT phone
FROM member
WHERE first_name = 'Carlo' AND last_name = 'Jacobs';

SELECT SUM(cost) AS total_pizza_cost
FROM expense
WHERE expense_description = 'Pizza';

SELECT COUNT(DISTINCT city) AS num_cities
FROM zip_code
WHERE county = 'Orange County' AND state = 'Virginia';

SELECT DISTINCT department
FROM major
WHERE college = 'College of Humanities and Social Sciences';

SELECT SUM(m.major_name = 'Finance') / SUM(m.major_name = 'Physics') AS ratio
FROM member mem
JOIN major m ON mem.link_to_major = m.major_id;

SELECT first_name, last_name, email
FROM member
WHERE position = 'Secretary';

SELECT SUM(spent) / COUNT(spent) AS avg_food_spent_per_event
FROM budget
WHERE category = 'Food' AND event_status = 'Closed';

SELECT SUM(CASE WHEN type = 'Community Service' THEN 1 ELSE 0 END) * 100.0 / COUNT(event_id) AS percentage
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT SUM(cost) AS total_expense
FROM expense
WHERE expense_date = '2019-08-20';

SELECT DISTINCT type
FROM event
WHERE location = 'MU 215';

SELECT SUM(CASE WHEN m.position = 'Member' AND mj.major_name = 'Business' THEN 1 ELSE 0 END) * 100.0 / COUNT(m.member_id) AS percentage
FROM member m
JOIN major mj ON m.link_to_major = mj.major_id;

SELECT SUM(CASE WHEN b.remaining < 0 THEN 1 ELSE 0 END) * 100.0 / COUNT(e.event_id) AS percentage
FROM event e
JOIN budget b ON b.link_to_event = e.event_id;

SELECT event_id, location, status
FROM event
WHERE event_date BETWEEN '2019-11-01' AND '2020-03-31';

SELECT
  (SELECT SUM(s1.weight_kg) FROM superhero s1 WHERE s1.full_name = 'Emil Blonsky') -
  (SELECT SUM(s2.weight_kg) FROM superhero s2 WHERE s2.full_name = 'Charles Chandler') AS weight_difference;

SELECT 100.0 * SUM(CASE WHEN c.colour = 'Blue' THEN 1 ELSE 0 END) / COUNT(s.superhero_name) AS percentage
FROM superhero s
LEFT JOIN colour c ON c.id = s.eye_colour_id;

SELECT CAST(SUM(CASE WHEN g.gender = 'Male' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN g.gender = 'Female' THEN 1 ELSE 0 END) AS ratio
FROM superhero s
JOIN gender g ON s.gender_id = g.id;

SELECT superhero_name
FROM superhero
WHERE height_cm = (SELECT MAX(height_cm) FROM superhero);

SELECT full_name
FROM superhero
WHERE weight_kg = 0 OR weight_kg IS NULL;

SELECT superhero_name
FROM superhero
WHERE height_cm = (SELECT MAX(height_cm) FROM superhero);

SELECT COUNT(*) AS total_superheroes
FROM superhero
WHERE full_name LIKE 'John%';

SELECT s.full_name
FROM superhero s
WHERE s.superhero_name = 'Alien';

SELECT SUM(CASE WHEN STRFTIME('%Y', Birthday) > '1930' THEN 1 ELSE 0 END) * 100.0 / COUNT(ID) AS percentage
FROM Patient
WHERE SEX = 'F';

SELECT SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) * 1.0 / SUM(CASE WHEN Admission = '-' THEN 1 ELSE 0 END) AS ratio
FROM Patient
WHERE Diagnosis = 'SLE';

SELECT SUM(CASE WHEN P.Birthday = '1959-02-18' AND L.Date LIKE '1981-11-%' THEN L.`T-CHO` ELSE 0 END) - SUM(CASE WHEN P.Birthday = '1959-02-18' AND L.Date LIKE '1981-12-%' THEN L.`T-CHO` ELSE 0 END) AS decrease_rate
FROM Patient AS P
JOIN Laboratory AS L ON L.ID = P.ID;

SELECT SUM(CASE WHEN UA <= 6.5 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM Laboratory
WHERE `U-PRO` > 0 AND `U-PRO` < 30;

SELECT SUM(CASE WHEN Diagnosis = 'BEHCET' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM Patient
WHERE SEX = 'M' AND YEAR(`First Date`) = '1981';

SELECT p.Description AS first_documented, p.Diagnosis AS disease
FROM Patient p
WHERE p.ID = 48473;

SELECT COUNT(DISTINCT p.ID)
FROM Patient p
WHERE p.SEX = 'F' AND p.Diagnosis = 'APS';

SELECT SUM(DIAGNOSIS LIKE '%ITP%') * 100.0 / SUM(DIAGNOSIS LIKE '%SLE%') AS proportion
FROM Examination
WHERE SYMPTOMS LIKE '%thrombocytopenia%';

SELECT ROUND(100.0 * SUM(CASE WHEN bond_type = '=' THEN 1 ELSE 0 END) / COUNT(bond_id), 5) AS percentage
FROM bond
WHERE molecule_id = 'TR008';

SELECT COUNT(DISTINCT b.molecule_id) AS num_molecules
FROM bond b
WHERE b.bond_type = '#';

SELECT label
FROM molecule
WHERE molecule_id IN ('TR000', 'TR001', 'TR002');

SELECT DISTINCT b.molecule_id
FROM bond b
WHERE b.bond_type = ' = ';

SELECT 100.0 * COUNT(DISTINCT CASE WHEN b.bond_type = '#' THEN m.molecule_id END) / COUNT(DISTINCT m.molecule_id) AS percent_triple_bond
FROM molecule m
LEFT JOIN bond b ON b.molecule_id = m.molecule_id;

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM molecule m
    WHERE m.molecule_id = 'TR124'
      AND m.label = '+'
) THEN 'Yes' ELSE 'No' END AS is_carcinogenic;

SELECT atom_id
FROM atom
WHERE molecule_id = 'TR186';

SELECT bond_type
FROM bond
WHERE bond_id = 'TR007_4_19';

SELECT
  (SELECT COUNT(*) FROM bond WHERE molecule_id = 'TR006' AND bond_type = ' = ') AS num_double_bonds,
  (SELECT label FROM molecule WHERE molecule_id = 'TR006') AS carcinogenic;

SELECT CASE WHEN label = '+' THEN 'carcinogenic' ELSE 'non-carcinogenic' END AS carcinogenic_status
FROM molecule
WHERE molecule_id = 'TR000';
